{"summary":"实现报警锁存：故障为 TRUE 时强制并保持 alarm 为 TRUE，且优先于确认边沿；仅在 fault 为 FALSE 且 acknowledge 出现上升沿时清除 alarm。每个扫描周期都更新 acknowledge 的历史状态，因此故障期间按住 acknowledge 不会在故障消失后清除报警，必须松开再按下。","code":"FUNCTION_BLOCK AcknowledgeLatch
VAR_INPUT
    fault : BOOL;
    acknowledge : BOOL;
END_VAR
VAR_OUTPUT
    alarm : BOOL := FALSE;
END_VAR
VAR
    prevAck : BOOL := FALSE;
    ackRising : BOOL := FALSE;
END_VAR

ackRising := acknowledge AND NOT prevAck;
prevAck := acknowledge;

IF fault THEN
    alarm := TRUE;
ELSIF ackRising THEN
    alarm := FALSE;
END_IF;

END_FUNCTION_BLOCK","assumptions":[]}
